Future<FinanceControlCenter> fetchFinanceControlCenter()async{await requireAdminAccess();final r=await supabase.rpc('admin_finance_control_center');final m=r is List&&r.isNotEmpty?r.first:r;if(m is Map)return FinanceControlCenter.fromSupabase(Map<String,dynamic>.from(m));throw Exception('Finance control center could not be loaded.');}
Future<List<FinanceAuditSnapshot>> fetchFinanceAuditSnapshots()async{await requireAdminAccess();final r=await supabase.rpc('admin_list_finance_audit_snapshots',params:{'p_limit':50});return (r as List).map((e)=>FinanceAuditSnapshot.fromSupabase(Map<String,dynamic>.from(e as Map))).toList();}
Future<void> captureFinanceAuditSnapshot(String note)async{await requireAdminAccess();await supabase.rpc('admin_capture_finance_audit_snapshot',params:{'p_note':note.trim()});}
